// Daily Protocol push server.
//
// A Cloudflare Worker with one Durable Object ("hub") that keeps the phone's
// push subscription, the reminder schedule the app sends it, and any pending
// rest-timer alert. The hub sets a Durable Object alarm for the next thing that
// is due, sends it as an encrypted Web Push message, and sets the next alarm.
//
// The VAPID key pair is generated by the hub on first use and kept in its
// storage, so there is no secret to configure. The app fetches the public key
// from GET /key before subscribing.

import { DurableObject } from "cloudflare:workers";
import { applyPrefs, clip, dueBetween, encryptPayload, nextDue, rid, vapidJwt, b64u } from "./lib.js";

const MAX_SUBS = 5;
const CATCH_UP_MS = 10 * 60 * 1000; // after downtime, only send what came due in the last 10 min

export default {
  async fetch(req, env) {
    const cors = corsHeaders(req, env);
    if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    const hub = env.HUB.get(env.HUB.idFromName("main"));
    const res = await hub.fetch(req);
    const out = new Response(res.body, res);
    for (const [k, v] of Object.entries(cors)) out.headers.set(k, v);
    return out;
  },
};

function corsHeaders(req, env) {
  const origin = req.headers.get("Origin") || "";
  const allowed = (env.ALLOWED_ORIGINS || "").split(",").map((s) => s.trim()).filter(Boolean);
  return {
    "Access-Control-Allow-Origin": allowed.includes(origin) ? origin : allowed[0] || "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Max-Age": "86400",
    Vary: "Origin",
  };
}

const json = (data, status = 200) =>
  new Response(JSON.stringify(data), { status, headers: { "Content-Type": "application/json" } });

export class Hub extends DurableObject {
  async fetch(req) {
    const url = new URL(req.url);
    try {
      if (req.method === "GET" && url.pathname === "/key") return json({ publicKey: (await this.vapid()).publicKey });
      if (req.method === "GET" && url.pathname === "/health") return json({ ok: true });
      if (req.method !== "POST") return json({ error: "not_found" }, 404);
      const body = await req.json().catch(() => null);
      if (!body) return json({ error: "bad_json" }, 400);
      switch (url.pathname) {
        case "/subscribe": return await this.subscribe(body);
        case "/prefs": return await this.withSub(body, (s) => this.setPrefs(s, body));
        case "/rest": return await this.withSub(body, (s) => this.setRest(s, body));
        case "/test": return await this.withSub(body, (s) => this.test(s));
        case "/unsubscribe": return await this.withSub(body, (s) => this.unsubscribe(s));
      }
      return json({ error: "not_found" }, 404);
    } catch (err) {
      return json({ error: "server_error", message: String(err && err.message || err) }, 500);
    }
  }

  // ---------- storage ----------
  async subs() { return (await this.ctx.storage.get("subs")) || {}; }
  async saveSubs(subs) { await this.ctx.storage.put("subs", subs); }

  async vapid() {
    let v = await this.ctx.storage.get("vapid");
    if (!v) {
      const kp = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
      const raw = new Uint8Array(await crypto.subtle.exportKey("raw", kp.publicKey));
      v = { publicKey: b64u(raw), privateJwk: await crypto.subtle.exportKey("jwk", kp.privateKey) };
      await this.ctx.storage.put("vapid", v);
    }
    return v;
  }

  async withSub(body, fn) {
    const subs = await this.subs();
    const s = subs[body.id];
    if (!s || s.secret !== body.secret) return json({ error: "unknown_subscription" }, 404);
    return fn(s, subs);
  }

  // ---------- endpoints ----------
  async subscribe(body) {
    const sub = body.sub;
    if (!sub || typeof sub.endpoint !== "string" || !sub.keys || !sub.keys.p256dh || !sub.keys.auth)
      return json({ error: "bad_subscription" }, 400);
    if (!/^https:\/\//.test(sub.endpoint) && !this.env.DEV_ALLOW_HTTP) return json({ error: "bad_endpoint" }, 400);
    const subs = await this.subs();
    let s = Object.values(subs).find((x) => x.sub.endpoint === sub.endpoint);
    if (!s) {
      const ids = Object.keys(subs).sort((a, b) => subs[a].created - subs[b].created);
      while (ids.length >= MAX_SUBS) delete subs[ids.shift()];
      s = { id: rid(12), secret: rid(24), created: Date.now() };
      subs[s.id] = s;
    }
    s.sub = { endpoint: sub.endpoint, keys: { p256dh: sub.keys.p256dh, auth: sub.keys.auth } };
    applyPrefs(s, body);
    s.lastRun = Date.now();
    await this.saveSubs(subs);
    await this.reschedule();
    return json({ id: s.id, secret: s.secret, publicKey: (await this.vapid()).publicKey });
  }

  async setPrefs(s, body) {
    const subs = await this.subs();
    applyPrefs(subs[s.id], body);
    await this.saveSubs(subs);
    await this.reschedule();
    return json({ ok: true, next: nextDue(subs[s.id], Date.now()) });
  }

  async setRest(s, body) {
    const subs = await this.subs();
    const at = Number(body.at);
    if (at && at > Date.now() && at < Date.now() + 60 * 60 * 1000) {
      subs[s.id].rest = { at, title: clip(body.title, 80) || "Rest's up", body: clip(body.body, 200) || "Next set." };
    } else delete subs[s.id].rest;
    await this.saveSubs(subs);
    await this.reschedule();
    return json({ ok: true });
  }

  async test(s) {
    const r = await this.send(s, { title: "Notifications are on", body: "Reminders will show up here, even when your phone is locked.", tag: "test", url: "./" });
    return json({ ok: r.ok, status: r.status });
  }

  async unsubscribe(s) {
    const subs = await this.subs();
    delete subs[s.id];
    await this.saveSubs(subs);
    await this.reschedule();
    return json({ ok: true });
  }

  // ---------- scheduling ----------
  async reschedule() {
    const subs = await this.subs(), now = Date.now();
    let next = Infinity;
    for (const s of Object.values(subs)) {
      if (s.rest) next = Math.min(next, s.rest.at);
      const d = nextDue(s, Math.max(now, s.lastRun || 0));
      if (d) next = Math.min(next, d.at);
    }
    if (next === Infinity) await this.ctx.storage.deleteAlarm();
    else await this.ctx.storage.setAlarm(Math.max(next, now + 500));
  }

  async alarm() {
    const subs = await this.subs(), now = Date.now();
    for (const s of Object.values(subs)) {
      const msgs = [];
      if (s.rest && s.rest.at <= now + 1000) {
        msgs.push({ title: s.rest.title, body: s.rest.body, tag: "rest", url: "./#train" });
        delete s.rest;
      }
      const from = Math.max(s.lastRun || now - CATCH_UP_MS, now - CATCH_UP_MS);
      for (const d of dueBetween(s, from, now + 1000)) msgs.push({ title: d.r.title, body: d.r.body, tag: d.r.id, url: d.r.url || "./" });
      s.lastRun = now + 1000;
      for (const m of msgs) {
        const r = await this.send(s, m);
        if (r.status === 404 || r.status === 410) { delete subs[s.id]; break; }
      }
    }
    await this.saveSubs(subs);
    await this.reschedule();
  }

  // ---------- Web Push ----------
  async send(s, payload) {
    const v = await this.vapid();
    const endpoint = new URL(s.sub.endpoint);
    const jwt = await vapidJwt(v.privateJwk, endpoint.origin, "https://malachixmoore0-coder.github.io/daily-protocol/");
    const body = await encryptPayload(s.sub, new TextEncoder().encode(JSON.stringify(payload)));
    const res = await fetch(s.sub.endpoint, {
      method: "POST",
      headers: {
        Authorization: `vapid t=${jwt}, k=${v.publicKey}`,
        "Content-Encoding": "aes128gcm",
        "Content-Type": "application/octet-stream",
        TTL: "3600",
        Urgency: "high",
        ...(payload.tag ? { Topic: payload.tag.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32) } : {}),
      },
      body,
    });
    return { ok: res.ok, status: res.status };
  }
}
